import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_25_bc_overview.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_25_trajectory_split.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_25_bc_evaluation.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_25_bc_loss.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_25_driving_distribution.png",g=JSON.parse('{"title":"不知道奖励怎么写？先用行为克隆学会专家怎么做","description":"当任务奖励难以定义、环境交互昂贵或安全探索不可接受时，最直接的办法是收集专家状态—动作示范，把策略学习先转成监督学习。Behavior Cloning（行为克隆，BC）用专家动作作为标签，训练策略在看到相似状态时输出相似动作。它可以快速得到一个可运行的初始策略，却不能自动理解专家为什么这样做，也不能","frontmatter":{"title":"不知道奖励怎么写？先用行为克隆学会专家怎么做","description":"当任务奖励难以定义、环境交互昂贵或安全探索不可接受时，最直接的办法是收集专家状态—动作示范，把策略学习先转成监督学习。Behavior Cloning（行为克隆，BC）用专家动作作为标签，训练策略在看到相似状态时输出相似动作。它可以快速得到一个可运行的初始策略，却不能自动理解专家为什么这样做，也不能","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":7,"source":"2026-08-13/rl_series_25_behavior_cloning.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_25_bc_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-25-behavior-cloning"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"不知道奖励怎么写？先用行为克隆学会专家怎么做"}],["meta",{"property":"og:description","content":"当任务奖励难以定义、环境交互昂贵或安全探索不可接受时，最直接的办法是收集专家状态—动作示范，把策略学习先转成监督学习。Behavior Cloning（行为克隆，BC）用专家动作作为标签，训练策略在看到相似状态时输出相似动作。它可以快速得到一个可运行的初始策略，却不能自动理解专家为什么这样做，也不能"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-25-behavior-cloning"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_25_bc_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"不知道奖励怎么写？先用行为克隆学会专家怎么做"}],["meta",{"name":"twitter:description","content":"当任务奖励难以定义、环境交互昂贵或安全探索不可接受时，最直接的办法是收集专家状态—动作示范，把策略学习先转成监督学习。Behavior Cloning（行为克隆，BC）用专家动作作为标签，训练策略在看到相似状态时输出相似动作。它可以快速得到一个可运行的初始策略，却不能自动理解专家为什么这样做，也不能"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_25_bc_overview.png"}]],"prev":{"text":"一个目标太大怎么办？分层强化学习与 Options 框架","link":"/rl/rl-series-24-hierarchical-options"},"next":{"text":"专家只看训练集不够：DAgger 如何修复行为克隆的分布偏移","link":"/rl/rl-series-26-dagger-dataset-aggregation"}},"headers":[],"relativePath":"rl/rl-series-25-behavior-cloning.md","filePath":"rl/rl-series-25-behavior-cloning.md","lastUpdated":null}'),c={name:"rl/rl-series-25-behavior-cloning.md"};function d(p,a,_,b,u,q){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="不知道奖励怎么写-先用行为克隆学会专家怎么做" tabindex="-1">不知道奖励怎么写？先用行为克隆学会专家怎么做 <a class="header-anchor" href="#不知道奖励怎么写-先用行为克隆学会专家怎么做" aria-label="Permalink to &quot;不知道奖励怎么写？先用行为克隆学会专家怎么做&quot;">​</a></h1><p>当任务奖励难以定义、环境交互昂贵或安全探索不可接受时，最直接的办法是收集专家状态—动作示范，把策略学习先转成监督学习。Behavior Cloning（行为克隆，BC）用专家动作作为标签，训练策略在看到相似状态时输出相似动作。它可以快速得到一个可运行的初始策略，却不能自动理解专家为什么这样做，也不能保证离开专家状态分布后仍然稳定。</p><p>行为克隆是模仿学习的入口，不是强化学习的替代品。它回答“专家在这个观测下做了什么”，而不是“哪个动作在长期目标下最优”。自动驾驶中一处小转角误差会改变后续车辆状态，策略随后看到训练数据中没有的场景，误差可能连续累积。理解 BC 的价值与边界，是后续 DAgger（数据集聚合）和逆强化学习的前提。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-bc-把示范变成监督数据" tabindex="-1">1.1 BC 把示范变成监督数据 <a class="header-anchor" href="#_1-1-bc-把示范变成监督数据" aria-label="Permalink to &quot;1.1 BC 把示范变成监督数据&quot;">​</a></h3><p>数据集通常是 (D={(o_i,a_i)})，策略最小化专家动作预测损失。</p><h3 id="_1-2-bc-学的是专家分布而非任务奖励" tabindex="-1">1.2 BC 学的是专家分布而非任务奖励 <a class="header-anchor" href="#_1-2-bc-学的是专家分布而非任务奖励" aria-label="Permalink to &quot;1.2 BC 学的是专家分布而非任务奖励&quot;">​</a></h3><p>没有环境奖励也能训练，但策略质量受专家覆盖、标签一致性和观测设计限制。</p><h3 id="_1-3-自回归执行会放大单步误差" tabindex="-1">1.3 自回归执行会放大单步误差 <a class="header-anchor" href="#_1-3-自回归执行会放大单步误差" aria-label="Permalink to &quot;1.3 自回归执行会放大单步误差&quot;">​</a></h3><p>动作影响下一状态，预测偏差改变后续观测分布，测试时误差分布与训练集不再相同。</p><h3 id="_1-4-bc-适合初始化和基线" tabindex="-1">1.4 BC 适合初始化和基线 <a class="header-anchor" href="#_1-4-bc-适合初始化和基线" aria-label="Permalink to &quot;1.4 BC 适合初始化和基线&quot;">​</a></h3><p>它能提供安全的冷启动、减少探索成本，也能作为强化学习或 DAgger 的初始策略，但不应把训练集准确率当成闭环性能。</p><p><img src="'+o+'" alt="行为克隆从专家观测到策略动作"></p><h2 id="二、行为克隆的数据长什么样" tabindex="-1">二、行为克隆的数据长什么样 <a class="header-anchor" href="#二、行为克隆的数据长什么样" aria-label="Permalink to &quot;二、行为克隆的数据长什么样&quot;">​</a></h2><h3 id="_2-1-专家轨迹包含状态和动作" tabindex="-1">2.1 专家轨迹包含状态和动作 <a class="header-anchor" href="#_2-1-专家轨迹包含状态和动作" aria-label="Permalink to &quot;2.1 专家轨迹包含状态和动作&quot;">​</a></h3><p>一条轨迹可以写成 (\\tau=(s_0,a_0,s_1,a_1,\\ldots))。实际系统常用观测 (o_t) 代替完整状态。</p><h3 id="_2-2-标签必须与控制周期对齐" tabindex="-1">2.2 标签必须与控制周期对齐 <a class="header-anchor" href="#_2-2-标签必须与控制周期对齐" aria-label="Permalink to &quot;2.2 标签必须与控制周期对齐&quot;">​</a></h3><p>观测时间戳、专家动作时间戳、执行延迟和控制周期不一致，会让网络学到错误的因果关系。</p><h3 id="_2-3-专家数据要覆盖恢复行为" tabindex="-1">2.3 专家数据要覆盖恢复行为 <a class="header-anchor" href="#_2-3-专家数据要覆盖恢复行为" aria-label="Permalink to &quot;2.3 专家数据要覆盖恢复行为&quot;">​</a></h3><p>只记录专家在理想路线上的动作，数据集缺少偏离、纠偏和紧急制动状态。策略一旦偏离就无法查询合理动作。</p><h3 id="_2-4-多专家标签可能互相冲突" tabindex="-1">2.4 多专家标签可能互相冲突 <a class="header-anchor" href="#_2-4-多专家标签可能互相冲突" aria-label="Permalink to &quot;2.4 多专家标签可能互相冲突&quot;">​</a></h3><p>不同驾驶风格对同一观测可能选择不同动作。应记录风格、场景和置信度，不能把冲突标签当作单一真值。</p><p><img src="'+l+'" alt="行为克隆按场景划分轨迹，避免随机切帧造成数据泄漏"></p><h2 id="三、bc-的损失如何定义" tabindex="-1">三、BC 的损失如何定义 <a class="header-anchor" href="#三、bc-的损失如何定义" aria-label="Permalink to &quot;三、BC 的损失如何定义&quot;">​</a></h2><h3 id="_3-1-离散动作使用交叉熵" tabindex="-1">3.1 离散动作使用交叉熵 <a class="header-anchor" href="#_3-1-离散动作使用交叉熵" aria-label="Permalink to &quot;3.1 离散动作使用交叉熵&quot;">​</a></h3><p>策略输出动作分布 (\\pi_\\theta(a|o))，损失为：</p><p>$$ L_{BC}=-\\mathbb E_{(o,a)\\sim D}\\log\\pi_\\theta(a|o) $$</p><h3 id="_3-2-连续动作使用回归或分布似然" tabindex="-1">3.2 连续动作使用回归或分布似然 <a class="header-anchor" href="#_3-2-连续动作使用回归或分布似然" aria-label="Permalink to &quot;3.2 连续动作使用回归或分布似然&quot;">​</a></h3><p>转角和加速度可用均方误差，也可让网络输出高斯分布并最大化专家动作似然。损失选择会影响多模态动作的表达。</p><h3 id="_3-3-动作维度需要分别归一化" tabindex="-1">3.3 动作维度需要分别归一化 <a class="header-anchor" href="#_3-3-动作维度需要分别归一化" aria-label="Permalink to &quot;3.3 动作维度需要分别归一化&quot;">​</a></h3><p>转角、速度和加速度量纲不同。未归一化时，大数值维度会支配梯度。</p><h3 id="_3-4-训练损失不是闭环指标" tabindex="-1">3.4 训练损失不是闭环指标 <a class="header-anchor" href="#_3-4-训练损失不是闭环指标" aria-label="Permalink to &quot;3.4 训练损失不是闭环指标&quot;">​</a></h3><p>离线动作误差下降只说明在专家观测上预测更接近，不能证明策略在自身诱导状态上仍然稳定。</p><p><img src="'+h+'" alt="行为克隆评价同时覆盖离线预测、闭环行为、安全和泛化"></p><p><img src="'+n+'" alt="行为克隆的分类、回归与分布策略"></p><h2 id="四、协变量偏移为什么是核心问题" tabindex="-1">四、协变量偏移为什么是核心问题 <a class="header-anchor" href="#四、协变量偏移为什么是核心问题" aria-label="Permalink to &quot;四、协变量偏移为什么是核心问题&quot;">​</a></h2><h3 id="_4-1-训练看到的是专家状态分布" tabindex="-1">4.1 训练看到的是专家状态分布 <a class="header-anchor" href="#_4-1-训练看到的是专家状态分布" aria-label="Permalink to &quot;4.1 训练看到的是专家状态分布&quot;">​</a></h3><p>数据分布近似 (d_{\\pi_E}(s))，其中 (\\pi_E) 是专家策略。</p><h3 id="_4-2-部署看到的是学习策略分布" tabindex="-1">4.2 部署看到的是学习策略分布 <a class="header-anchor" href="#_4-2-部署看到的是学习策略分布" aria-label="Permalink to &quot;4.2 部署看到的是学习策略分布&quot;">​</a></h3><p>闭环运行时状态来自 (d_{\\pi_\\theta}(s))。只要策略有一点误差，二者就会逐步分离。</p><h3 id="_4-3-误差会沿时间累积" tabindex="-1">4.3 误差会沿时间累积 <a class="header-anchor" href="#_4-3-误差会沿时间累积" aria-label="Permalink to &quot;4.3 误差会沿时间累积&quot;">​</a></h3><p>单步动作误差可能造成位置和速度偏差，偏差又导致下一步动作预测更差，最终发生失控或碰撞。</p><h3 id="_4-4-数据量不能替代分布覆盖" tabindex="-1">4.4 数据量不能替代分布覆盖 <a class="header-anchor" href="#_4-4-数据量不能替代分布覆盖" aria-label="Permalink to &quot;4.4 数据量不能替代分布覆盖&quot;">​</a></h3><p>复制大量相似专家直行片段不能解决弯道、偏离和异常场景覆盖不足。有效数据多样性比样本总数更重要。</p><h2 id="五、行为克隆如何与强化学习衔接" tabindex="-1">五、行为克隆如何与强化学习衔接 <a class="header-anchor" href="#五、行为克隆如何与强化学习衔接" aria-label="Permalink to &quot;五、行为克隆如何与强化学习衔接&quot;">​</a></h2><h3 id="_5-1-bc-作为策略初始化" tabindex="-1">5.1 BC 作为策略初始化 <a class="header-anchor" href="#_5-1-bc-作为策略初始化" aria-label="Permalink to &quot;5.1 BC 作为策略初始化&quot;">​</a></h3><p>先让策略模仿专家，再使用环境奖励微调，可以降低随机探索阶段的失败率。</p><h3 id="_5-2-bc-作为安全基线" tabindex="-1">5.2 BC 作为安全基线 <a class="header-anchor" href="#_5-2-bc-作为安全基线" aria-label="Permalink to &quot;5.2 BC 作为安全基线&quot;">​</a></h3><p>在强化学习策略发布前，可与 BC 策略、经典控制器和安全过滤器比较，定位学习策略是否引入额外风险。</p><h3 id="_5-3-bc-数据可提供价值预训练" tabindex="-1">5.3 BC 数据可提供价值预训练 <a class="header-anchor" href="#_5-3-bc-数据可提供价值预训练" aria-label="Permalink to &quot;5.3 BC 数据可提供价值预训练&quot;">​</a></h3><p>专家轨迹能帮助评论家看到高质量状态区域，但价值标签仍需由奖励和转移定义，不能把专家动作直接当成 Q 真值。</p><h3 id="_5-4-微调会改变分布" tabindex="-1">5.4 微调会改变分布 <a class="header-anchor" href="#_5-4-微调会改变分布" aria-label="Permalink to &quot;5.4 微调会改变分布&quot;">​</a></h3><p>强化学习接管后策略可能离开专家分布。需要继续记录与专家的偏差、任务回报和安全介入，而不是只保留初始 BC 指标。</p><h2 id="六、自动驾驶中如何建立-bc-基线" tabindex="-1">六、自动驾驶中如何建立 BC 基线 <a class="header-anchor" href="#六、自动驾驶中如何建立-bc-基线" aria-label="Permalink to &quot;六、自动驾驶中如何建立 BC 基线&quot;">​</a></h2><h3 id="_6-1-明确专家动作的控制层级" tabindex="-1">6.1 明确专家动作的控制层级 <a class="header-anchor" href="#_6-1-明确专家动作的控制层级" aria-label="Permalink to &quot;6.1 明确专家动作的控制层级&quot;">​</a></h3><p>专家可以标注方向盘、加速度，也可以标注局部轨迹、目标速度或行为意图。输出层级不同，闭环评估和安全约束也不同。</p><h3 id="_6-2-观测要包含真正可用的信息" tabindex="-1">6.2 观测要包含真正可用的信息 <a class="header-anchor" href="#_6-2-观测要包含真正可用的信息" aria-label="Permalink to &quot;6.2 观测要包含真正可用的信息&quot;">​</a></h3><p>训练输入不能包含部署时没有的未来轨迹、人工标注或不可实时获得的全局状态。</p><h3 id="_6-3-训练集按场景而非随机帧划分" tabindex="-1">6.3 训练集按场景而非随机帧划分 <a class="header-anchor" href="#_6-3-训练集按场景而非随机帧划分" aria-label="Permalink to &quot;6.3 训练集按场景而非随机帧划分&quot;">​</a></h3><p>相邻视频帧高度相关。按帧随机划分会让训练和测试共享几乎相同场景，夸大泛化性能。</p><p><img src="'+s+'" alt="自动驾驶行为克隆的数据分布与闭环偏移"></p><h2 id="七、一个最小实验怎样设计" tabindex="-1">七、一个最小实验怎样设计 <a class="header-anchor" href="#七、一个最小实验怎样设计" aria-label="Permalink to &quot;七、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_7-1-采集专家轨迹和偏离轨迹" tabindex="-1">7.1 采集专家轨迹和偏离轨迹 <a class="header-anchor" href="#_7-1-采集专家轨迹和偏离轨迹" aria-label="Permalink to &quot;7.1 采集专家轨迹和偏离轨迹&quot;">​</a></h3><p>除正常驾驶外，记录受控扰动、不同起点、不同天气和专家纠偏动作。</p><h3 id="_7-2-比较离线误差与闭环指标" tabindex="-1">7.2 比较离线误差与闭环指标 <a class="header-anchor" href="#_7-2-比较离线误差与闭环指标" aria-label="Permalink to &quot;7.2 比较离线误差与闭环指标&quot;">​</a></h3><p>报告动作误差、轨迹偏差、碰撞率、越界率、接管次数和恢复成功率。</p><h3 id="_7-3-进行数据覆盖消融" tabindex="-1">7.3 进行数据覆盖消融 <a class="header-anchor" href="#_7-3-进行数据覆盖消融" aria-label="Permalink to &quot;7.3 进行数据覆盖消融&quot;">​</a></h3><p>逐步加入弯道、低附着、延迟和动态障碍，观察闭环性能是否随覆盖改善。</p><h3 id="_7-4-记录多专家风格" tabindex="-1">7.4 记录多专家风格 <a class="header-anchor" href="#_7-4-记录多专家风格" aria-label="Permalink to &quot;7.4 记录多专家风格&quot;">​</a></h3><p>比较混合专家、单一专家和带风格条件策略，检查平均动作是否生成任何专家都不会执行的危险行为。</p><h2 id="八、最常见的实现错误" tabindex="-1">八、最常见的实现错误 <a class="header-anchor" href="#八、最常见的实现错误" aria-label="Permalink to &quot;八、最常见的实现错误&quot;">​</a></h2><h3 id="_8-1-把观测复制成状态" tabindex="-1">8.1 把观测复制成状态 <a class="header-anchor" href="#_8-1-把观测复制成状态" aria-label="Permalink to &quot;8.1 把观测复制成状态&quot;">​</a></h3><p>相机观测不等于完整车辆状态，策略可能需要历史帧或滤波状态处理部分可观测性。</p><h3 id="_8-2-随机切分相邻帧" tabindex="-1">8.2 随机切分相邻帧 <a class="header-anchor" href="#_8-2-随机切分相邻帧" aria-label="Permalink to &quot;8.2 随机切分相邻帧&quot;">​</a></h3><p>数据泄漏会使离线准确率虚高，必须按路线、日期、场景或驾驶员分组切分。</p><h3 id="_8-3-忽略动作延迟" tabindex="-1">8.3 忽略动作延迟 <a class="header-anchor" href="#_8-3-忽略动作延迟" aria-label="Permalink to &quot;8.3 忽略动作延迟&quot;">​</a></h3><p>网络预测的是当前动作还是延迟后执行动作，必须在数据定义和仿真接口中一致。</p><h3 id="_8-4-只追求平均动作误差" tabindex="-1">8.4 只追求平均动作误差 <a class="header-anchor" href="#_8-4-只追求平均动作误差" aria-label="Permalink to &quot;8.4 只追求平均动作误差&quot;">​</a></h3><p>安全关键的刹车、避障和恢复动作可能样本少但影响大，需要分层指标和场景加权。</p><h2 id="九、学到什么程度才算掌握" tabindex="-1">九、学到什么程度才算掌握 <a class="header-anchor" href="#九、学到什么程度才算掌握" aria-label="Permalink to &quot;九、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_9-1-能写出-bc-数据与损失" tabindex="-1">9.1 能写出 BC 数据与损失 <a class="header-anchor" href="#_9-1-能写出-bc-数据与损失" aria-label="Permalink to &quot;9.1 能写出 BC 数据与损失&quot;">​</a></h3><p>你应能区分观测、动作、专家策略、策略分布和动作归一化。</p><h3 id="_9-2-能解释协变量偏移" tabindex="-1">9.2 能解释协变量偏移 <a class="header-anchor" href="#_9-2-能解释协变量偏移" aria-label="Permalink to &quot;9.2 能解释协变量偏移&quot;">​</a></h3><p>你应能说明为什么单步预测准确不等于闭环稳定，以及误差如何改变后续状态分布。</p><h3 id="_9-3-能设计闭环评估" tabindex="-1">9.3 能设计闭环评估 <a class="header-anchor" href="#_9-3-能设计闭环评估" aria-label="Permalink to &quot;9.3 能设计闭环评估&quot;">​</a></h3><p>你应能把离线损失与任务成功、安全和恢复指标分开报告。</p><h3 id="_9-4-能进入-dagger" tabindex="-1">9.4 能进入 DAgger <a class="header-anchor" href="#_9-4-能进入-dagger" aria-label="Permalink to &quot;9.4 能进入 DAgger&quot;">​</a></h3><p>下一篇将讨论如何让专家给学习策略自己访问到的状态重新打标签。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter11/chapter11.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十一章行为克隆部分</a></p><p><a href="https://arxiv.org/abs/1011.0686" target="_blank" rel="noreferrer">Ross、Gordon 与 Bagnell《A Reduction of Imitation Learning and Structured Prediction to No-Regret Online Learning》</a></p><p><a href="https://papers.nips.cc/paper/1988/hash/7cce53cf90577442771720a370c3c723-Abstract.html" target="_blank" rel="noreferrer">Pomerleau《ALVINN: An Autonomous Land Vehicle in a Neural Network》</a></p>',92)])])}const f=e(c,[["render",d]]);export{g as __pageData,f as default};
